/**
 * Agent-tool emission (M3): one authored tool → one
 * `elementum_agent_*_tool` resource block, in ei's dialect. The owning
 * AGENT's to-tf drives the pass and supplies both back-references
 * (`agent_id`, `app_id`) — this module never names the agent or app
 * resource types.
 *
 * Reference dialect (verified live, docs/design/m3-agent-dialect.md):
 * - self-app target → the app's own resource ref;
 * - cross-app target → a name-keyed `data.elementum_app` lookup whose
 *   label derives from the app NAME (ei's sanitize rule);
 * - tool fields → a local field resource ref, or an object-scoped
 *   `data.elementum_field` lookup when the typed target is foreign.
 */
import { type WorkspaceAspect } from "../../engine/build/context.js";
import { type TfBlock, type TfValue } from "../../engine/tf/index.js";
export interface ToolToTfContext {
    /** The owning app's refName + tfLabel (namespace) — self-target detection + app_id. */
    readonly appRefName: string;
    readonly appTfLabel: string;
    /** The owning agent's bare tfLabel (before apps_ prefix). */
    readonly agentBareTfLabel: string;
    /** Records a foreign-app data lookup for data.tf; returns its tfLabel. */
    foreignAppRef(tfLabel: string, name: string, namespace?: string): void;
    /** Records a foreign-ELEMENT data lookup for data.tf (board issue #42). */
    foreignElementRef(tfLabel: string, name: string, namespace?: string): void;
    foreignAutomationRef?(tfLabel: string, name: string, owner: {
        readonly kind: "app" | "element";
        readonly refName: string;
        readonly name: string;
        readonly namespace?: string;
    }): void;
    /** Records a `data.elementum_field` lookup for a field owned by a foreign app/element. */
    foreignFieldRef(type: string, tfLabel: string, objectId: TfValue, name: string): void;
    /** App/element roots authored in this same workspace. */
    readonly workspaceAspects?: ReadonlyMap<string, WorkspaceAspect>;
    /** Records an app-scoped service-account lookup by name. */
    serviceAccountRef?(tfLabel: string, name: string): TfValue | void;
    /** App-local automations whose publish resource will be emitted in this build. */
    readonly activeAutomationRefNames?: ReadonlySet<string>;
    /** Degradations land here — reported by the caller, never silent. */
    readonly diagnostics: string[];
}
export interface ToolToTfResult {
    readonly block: TfBlock;
    /** `<resourceType>.<tfLabel>` — bookkeeping for the agent catalog. */
    readonly address: string;
}
/**
 * One authored tool entry (`{ createRecord: {...} }`) → its resource block;
 * undefined = degraded with a diagnostic (unimplemented sub-type, missing
 * target). The one hard error is an invalid tool name — the platform would
 * reject it at apply with an opaque message, so fail at build time instead.
 */
export declare function toolToTf(entry: Record<string, unknown>, ctx: ToolToTfContext): ToolToTfResult | undefined;
